'use strict';
const fs=require('fs'),path=require('path');
const {chromium}=require('playwright');
const BASE=(process.env.P14_BASE_URL||'https://plan-ex.ru/erpv2/').replace(/\/+$/,'/'),U=p=>new URL(p,BASE).href;
const OUT=path.resolve(process.env.P14_OUT_DIR||'P14_output');fs.mkdirSync(OUT,{recursive:true});
const OWNER='p14_owner_260804221827';
function superadmin(){const e=process.env.P11_CREDENTIALS_B64||'';const a=e?JSON.parse(Buffer.from(e,'base64').toString('utf8')):[];return a.find(x=>String(x?.role||'').toUpperCase()==='SUPERADMIN')}
async function loginTry(browser,u,pw){const c=await browser.newContext({viewport:{width:1920,height:1080},deviceScaleFactor:1,ignoreHTTPSErrors:true,locale:'ru-RU',timezoneId:'Europe/Moscow'}),p=await c.newPage();let ok=false;try{await p.goto(U('login'),{waitUntil:'domcontentloaded',timeout:45000});await p.locator('input[name="username"],input[name="email"],input[type="email"],input[type="text"]').first().fill(u);await p.locator('input[type="password"]').first().fill(pw);await Promise.all([p.waitForLoadState('domcontentloaded',{timeout:12000}).catch(()=>{}),p.locator('button[type="submit"],input[type="submit"]').first().click()]);await p.waitForTimeout(500);ok=!/\/login(?:[/?#]|$)/i.test(p.url())}catch{}return{ok,context:c,page:p}}
function candidatesFrom(text,vals){const out=[];for(const v of vals)out.push(String(v));for(const m of String(text||'').matchAll(/[A-Za-z0-9!@#$%^&*()_+\-=]{8,64}/g))out.push(m[0]);return[...new Set(out)].filter(v=>v.length>=8&&v.length<=64&&!/^\d+$/.test(v)&&v!==OWNER&&!v.includes('@example.test')&&!/^\+?7\d{10}$/.test(v)&&!/^[a-f0-9]{64}$/i.test(v)&&!['superadmin','company_owner','senior_logist'].includes(v))}
(async()=>{const r={status:'FAIL',companyId:27,ownerUserId:16,resetHttpStatus:null,passwordCandidateCount:0,passwordLocated:false,ownerLoginPass:false,error:null};let b,sctx;try{const sa=superadmin();if(!sa)throw Error('superadmin unavailable');b=await chromium.launch({headless:true});let x=await loginTry(b,sa.username,sa.password);if(!x.ok)throw Error('superadmin login failed');sctx=x.context;const sp=x.page;await sp.goto(U('superadmin/companies/27/users'),{waitUntil:'domcontentloaded',timeout:45000});const f=sp.locator('form[action$="/superadmin/companies/27/owner/reset-password"]').first();if(!(await f.count()))throw Error('reset form unavailable');const nav=sp.waitForNavigation({waitUntil:'domcontentloaded',timeout:30000});await f.evaluate(form=>HTMLFormElement.prototype.submit.call(form));const response=await nav;r.resetHttpStatus=response?.status()??null;await sp.waitForTimeout(500);const vals=await sp.locator('input,textarea,code,pre,[data-password]').evaluateAll(ns=>ns.map(n=>n.value||n.getAttribute('data-password')||n.textContent||'').filter(Boolean));const body=await sp.locator('body').innerText().catch(()=>'');const list=candidatesFrom(body,vals);r.passwordCandidateCount=list.length;for(const candidate of list){const test=await loginTry(b,OWNER,candidate);if(test.ok){r.passwordLocated=true;r.ownerLoginPass=true;await test.page.goto(U('company/dashboard'),{waitUntil:'domcontentloaded',timeout:45000});await test.page.screenshot({path:path.join(OUT,'P14_OWNER_AFTER_PASSWORD_RESET_1920x1080.png'),fullPage:false});await test.context.close();break}await test.context.close()}r.status=r.ownerLoginPass?'PASS':'FAIL';for(let i=0;i<list.length;i++)list[i]=''}catch(e){r.error={name:e?.name||'Error',message:String(e?.message||e).replace(/[A-Za-z0-9!@#$%^&*()_+\-=]{12,}/g,'[REDACTED]').slice(0,500)}}finally{if(sctx)await sctx.close().catch(()=>{});if(b)await b.close().catch(()=>{});fs.writeFileSync(path.join(OUT,'P14_runtime_result.json'),JSON.stringify(r,null,2));console.log(`P14_OWNER_RESET=${r.status}`);process.exitCode=r.status==='PASS'?0:1}})().catch(()=>{console.log('P14_OWNER_RESET=FAIL');process.exitCode=1});
